import { Fragment, useState } from "react";
import { Check, ShieldCheck } from "lucide-react";
import { cloneJsonValue, type JsonValue } from "@agentdock-ai/contracts";
import type {
  RenderApproval,
  RenderApprovalAction,
} from "@agentdock-ai/ui-core";
import { ChatIcon } from "./icon";
import { ErrorState } from "./error-state";
import { Button } from "./ui/button";

type Decision = "approve" | "edit" | "reject";
const decisionTypes: Decision[] = ["approve", "edit", "reject"];
const labels = { approve: "Approve", edit: "Edit", reject: "Reject" };
const allowed = (action: RenderApprovalAction) =>
  action.allowedDecisions ?? decisionTypes;

export function ApprovalCard({
  approval,
  enabled,
  pending,
  error,
  onRespond,
}: {
  approval: RenderApproval;
  enabled: boolean;
  pending: boolean;
  error?: string;
  onRespond: (decisions: readonly JsonValue[]) => void;
}) {
  const resolved = approval.state === "resolved";
  const [choices, setChoices] = useState<Record<string, Decision>>({});
  const [edits, setEdits] = useState<Record<string, string>>({});
  const [editError, setEditError] = useState<string | null>(null);
  const locked = !enabled || pending;
  const toolApproval = approval.kind === "tool-approval";
  const hasActions = approval.actions.length > 0;
  const plural = approval.actions.length > 1 ? " all" : "";
  const selected = (action: RenderApprovalAction) => {
    const choice = choices[action.id];
    if (choice && allowed(action).includes(choice)) return choice;
    if (allowed(action).includes("approve")) return "approve";
    return allowed(action)[0];
  };
  const disabled =
    locked ||
    !hasActions ||
    approval.actions.some((action) => allowed(action).length === 0);
  const everyAllows = (type: Decision) =>
    approval.actions.every((action) => allowed(action).includes(type));

  function submit() {
    try {
      const decisions: JsonValue[] = approval.actions.map(
        (action): JsonValue => {
          const type = selected(action);
          if (!type)
            throw new Error("No decision is available for this action.");
          if (type !== "edit") return { type };
          const args = cloneJsonValue(
            JSON.parse(edits[action.id] ?? JSON.stringify(action.input)),
          );
          if (typeof args !== "object" || args === null || Array.isArray(args))
            throw new Error("Edited arguments must be a JSON object.");
          return { type: "edit", editedAction: { name: action.label, args } };
        },
      );
      setEditError(null);
      onRespond(decisions);
    } catch (cause) {
      setEditError(
        cause instanceof Error ? cause.message : "Enter valid JSON arguments.",
      );
    }
  }

  if (resolved)
    return (
      <section aria-label={approval.title} className="min-w-0 px-1">
        <div className="flex min-h-7 min-w-0 items-center gap-2 text-[13px] leading-5 text-muted-foreground">
          <ChatIcon icon={Check} size={13} aria-hidden="true" />
          <h3 className="shrink-0 text-foreground">Response received</h3>
          <p className="min-w-0 truncate">{approval.detail}</p>
        </div>
        {error && (
          <div className="mt-2">
            <ErrorState title="Response not confirmed" detail={error} />
          </div>
        )}
      </section>
    );

  const hint = !toolApproval
    ? "This app has no response control for this native interrupt."
    : pending
      ? "Sending your response…"
      : !enabled
        ? "This app can’t respond to this request here."
        : !hasActions
          ? "Continue this request in the app."
          : "The agent is paused until you respond.";

  return (
    <section
      aria-label={approval.title}
      className="min-w-0 rounded-2xl border border-border bg-card p-4 shadow-[0_1px_2px_0_rgb(0_0_0/0.04)]"
    >
      <div className="flex items-center gap-2">
        <ChatIcon
          icon={ShieldCheck}
          size={15}
          aria-hidden="true"
          className="text-muted-foreground"
        />
        <h3 className="min-w-0 text-[14px] font-medium leading-5">
          {approval.title}
        </h3>
      </div>
      <p className="mt-1 whitespace-pre-wrap text-[13px] leading-[1.6] text-muted-foreground [overflow-wrap:anywhere]">
        {approval.detail}
      </p>
      {toolApproval && hasActions && (
        <ul className="mt-3 space-y-1.5">
          {approval.actions.map((action) => {
            const decision = selected(action);
            return (
              <li
                key={action.id}
                className="min-w-0 rounded-lg bg-muted/50 px-3 py-2"
              >
                <div className="flex min-w-0 flex-wrap items-center justify-between gap-2">
                  <p className="min-w-0 text-[12.5px] font-medium leading-5 [overflow-wrap:anywhere]">
                    {action.label}
                  </p>
                  <select
                    aria-label={`${action.label} decision`}
                    className="rounded-md border border-border bg-background px-2 py-0.5 text-[12px] leading-5 text-foreground outline-none transition-[border-color,box-shadow] duration-150 focus:border-ring/60 focus:ring-4 focus:ring-ring/10 disabled:opacity-60 motion-reduce:transition-none"
                    value={decision ?? ""}
                    disabled={locked || allowed(action).length === 0}
                    onChange={(event) => {
                      const value = event.target.value;
                      if (
                        value === "approve" ||
                        value === "edit" ||
                        value === "reject"
                      )
                        setChoices((current) => ({
                          ...current,
                          [action.id]: value,
                        }));
                    }}
                  >
                    {allowed(action).map((type) => (
                      <option key={type} value={type}>
                        {labels[type]}
                      </option>
                    ))}
                  </select>
                </div>
                {action.description && (
                  <p className="mt-0.5 text-[12px] leading-5 text-muted-foreground">
                    {action.description}
                  </p>
                )}
                {decision === "edit" ? (
                  <textarea
                    aria-label={`${action.label} arguments`}
                    spellCheck={false}
                    className="mt-1.5 min-h-24 w-full resize-y rounded-md border border-border bg-background px-2.5 py-1.5 font-mono text-[12px] leading-5 text-foreground outline-none transition-[border-color,box-shadow] duration-150 focus:border-ring/60 focus:ring-4 focus:ring-ring/10 disabled:opacity-60 motion-reduce:transition-none"
                    value={
                      edits[action.id] ?? JSON.stringify(action.input, null, 2)
                    }
                    disabled={locked}
                    onChange={(event) =>
                      setEdits((current) => ({
                        ...current,
                        [action.id]: event.target.value,
                      }))
                    }
                  />
                ) : (
                  <Arguments
                    label={`${action.label} arguments`}
                    value={action.input}
                  />
                )}
                {allowed(action).length === 0 && (
                  <p className="mt-1 text-[12px] leading-5 text-muted-foreground">
                    This action has no available decisions.
                  </p>
                )}
              </li>
            );
          })}
        </ul>
      )}
      {editError && (
        <p role="alert" className="mt-2 text-xs leading-5 text-destructive">
          {editError}
        </p>
      )}
      {error && (
        <div className="mt-3">
          <ErrorState title="Response not confirmed" detail={error} />
        </div>
      )}
      <div className="mt-4 flex flex-wrap items-center justify-between gap-x-4 gap-y-3">
        <p className="min-w-0 flex-1 basis-48 text-xs leading-5 text-muted-foreground">
          {hint}
        </p>
        {toolApproval && hasActions && (
          <div className="flex flex-wrap items-center gap-1.5">
            {everyAllows("reject") && (
              <Button
                variant="outline"
                disabled={disabled}
                onClick={() =>
                  onRespond(approval.actions.map(() => ({ type: "reject" })))
                }
              >
                Reject{plural}
              </Button>
            )}
            {everyAllows("approve") && (
              <Button
                variant="outline"
                disabled={disabled}
                onClick={() =>
                  onRespond(approval.actions.map(() => ({ type: "approve" })))
                }
              >
                Approve{plural}
              </Button>
            )}
            <Button variant="primary" disabled={disabled} onClick={submit}>
              Submit decisions
            </Button>
          </div>
        )}
      </div>
    </section>
  );
}

/** Object arguments read as a key/value list; anything else falls back to JSON. */
function Arguments({ label, value }: { label: string; value: JsonValue }) {
  const entries =
    typeof value === "object" && value !== null && !Array.isArray(value)
      ? Object.entries(value)
      : null;
  if (entries?.length === 0) return null;
  return entries ? (
    <dl
      aria-label={label}
      className="mt-1 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-0.5 font-mono text-[12px] leading-5"
    >
      {entries.map(([key, entry]) => (
        <Fragment key={key}>
          <dt className="text-muted-foreground">{key}</dt>
          <dd className="min-w-0 text-foreground/80 [overflow-wrap:anywhere]">
            {typeof entry === "string" ? entry : JSON.stringify(entry)}
          </dd>
        </Fragment>
      ))}
    </dl>
  ) : (
    <pre
      aria-label={label}
      className="mt-1 max-h-40 overflow-auto whitespace-pre-wrap font-mono text-[12px] leading-5 text-foreground/80 [overflow-wrap:anywhere]"
    >
      {JSON.stringify(value, null, 2)}
    </pre>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import { Check, Copy } from "lucide-react";
import { ChatIcon } from "./icon";
import { Button } from "./ui/button";
export function ChatActionBar({ text }: { text: string }) {
  const [status, setStatus] = useState("");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  return (
    <div className="-ml-1.5 mt-2 flex items-center gap-1.5 text-xs text-muted-foreground">
      <Button
        aria-label={status === "Copied" ? "Answer copied" : "Copy answer"}
        title="Copy answer"
        size="icon"
        className="size-7 text-muted-foreground/80 [@media(pointer:coarse)]:size-9"
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(text);
            setStatus("Copied");
          } catch {
            setStatus("Copy unavailable. Select the text to copy.");
          }
          clearTimeout(timer.current);
          timer.current = setTimeout(() => setStatus(""), 2500);
        }}
      >
        {status === "Copied" ? (
          <ChatIcon icon={Check} size={14} aria-hidden="true" />
        ) : (
          <ChatIcon icon={Copy} size={14} aria-hidden="true" />
        )}
      </Button>
      <span role="status" className="text-[12px]">
        {status}
      </span>
    </div>
  );
}

import type { ReactNode } from "react";
import { cn } from "./utils";
export function ChatShell({
  children,
  footer,
  className,
  empty = false,
}: {
  children: ReactNode;
  footer: ReactNode;
  className?: string;
  empty?: boolean;
}) {
  return (
    <section
      aria-label="Agent conversation"
      className={cn(
        "relative flex h-full min-h-0 w-full min-w-0 flex-col bg-background font-sans text-[14px] text-foreground antialiased",
        empty ? "overflow-y-auto" : "overflow-hidden",
        className,
      )}
    >
      <div className={empty ? "hidden" : "contents"}>{children}</div>
      <div
        className={cn(
          "relative z-10 shrink-0 bg-background px-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
          empty ? "my-auto w-full py-10" : "pt-1 sm:pb-5",
        )}
      >
        {!empty && (
          // Lets the transcript fade out under the composer instead of being cut.
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 -top-6 h-6 bg-linear-to-t from-background to-transparent"
          />
        )}
        <div className="mx-auto w-full max-w-[42rem]">{footer}</div>
      </div>
    </section>
  );
}

"use client";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { ScrollToLatest } from "./scroll-to-latest";

export function ChatViewport({
  children,
  revision,
  latestUserId,
  empty,
}: {
  children: ReactNode;
  revision: unknown;
  latestUserId?: string;
  empty: boolean;
}) {
  const viewport = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const following = useRef(true);
  const previousUser = useRef(latestUserId);
  const lastScroll = useRef(0);
  const [showLatest, setShowLatest] = useState(false);
  function toBottom() {
    const el = viewport.current;
    if (!el) return;
    following.current = true;
    const behavior = window.matchMedia("(prefers-reduced-motion: reduce)")
      .matches
      ? "instant"
      : "smooth";
    el.scrollTo({ top: el.scrollHeight, behavior });
    lastScroll.current = el.scrollTop;
    setShowLatest(false);
  }
  useLayoutEffect(() => {
    const el = viewport.current;
    if (!el) return;
    if (previousUser.current !== latestUserId) {
      previousUser.current = latestUserId;
      following.current = true;
      const rows = el.querySelectorAll<HTMLElement>('[data-role="user"]');
      const row = rows.item(rows.length - 1);
      if (row) el.scrollTop = row.offsetTop - 24;
      lastScroll.current = el.scrollTop;
      setShowLatest(false);
    } else if (following.current) {
      el.scrollTop = el.scrollHeight;
      lastScroll.current = el.scrollTop;
    } else setShowLatest(el.scrollHeight - el.scrollTop - el.clientHeight > 48);
  }, [revision, latestUserId]);
  useLayoutEffect(() => {
    if (!viewport.current || !content.current) return;
    const observer = new ResizeObserver(() => {
      if (following.current && viewport.current) {
        viewport.current.scrollTop = viewport.current.scrollHeight;
        lastScroll.current = viewport.current.scrollTop;
      }
    });
    observer.observe(viewport.current);
    observer.observe(content.current);
    return () => observer.disconnect();
  }, []);
  return (
    <div className="relative flex min-h-0 flex-1 flex-col">
      <div
        ref={viewport}
        tabIndex={0}
        role="region"
        aria-label="Conversation messages"
        className="relative min-h-0 flex-1 overflow-x-hidden overflow-y-auto overscroll-contain outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring [overflow-anchor:none] [scrollbar-gutter:stable]"
        onScroll={() => {
          const el = viewport.current!;
          const nearBottom =
            el.scrollHeight - el.scrollTop - el.clientHeight < 48;
          if (el.scrollTop < lastScroll.current - 1) following.current = false;
          else if (nearBottom) following.current = true;
          lastScroll.current = el.scrollTop;
          setShowLatest(!nearBottom);
        }}
        onClickCapture={(event) => {
          // Expanding a disclosure should preserve the reader's place.
          if (
            event.target instanceof Element &&
            event.target.closest("[aria-expanded]")
          )
            following.current = false;
        }}
        onKeyDownCapture={(event) => {
          if (
            event.key === "PageUp" ||
            event.key === "Home" ||
            event.key === "ArrowUp"
          )
            following.current = false;
        }}
      >
        <div ref={content} className={cnContent(empty)}>
          {children}
        </div>
      </div>
      <ScrollToLatest onClick={toBottom} visible={showLatest} />
    </div>
  );
}
function cnContent(empty: boolean) {
  return `mx-auto flex w-full max-w-[44rem] flex-col px-4 pt-8 pb-8 ${empty ? "min-h-full justify-center" : "gap-6 pb-12"}`;
}

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { MessagesSquare, PanelLeft, X } from "lucide-react";
import { ChatIcon } from "./icon";
import { cn } from "./utils";
const iconButton =
  "flex size-7 items-center justify-center rounded-lg text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:size-9";
export function ChatWorkspace({
  children,
  sidebar,
  title = "New chat",
  brand = "Agentdock",
  actions,
  className,
}: {
  children: ReactNode;
  sidebar: ReactNode;
  title?: string;
  brand?: string;
  actions?: ReactNode;
  className?: string;
}) {
  const doubleClickDelayMs = 250;
  const [expanded, setExpanded] = useState(true);
  const mobile = useRef<HTMLDialogElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    mobile.current?.close();
    return () => {
      if (closeTimer.current) clearTimeout(closeTimer.current);
    };
  }, [title]);
  const brandMark = (
    <span className="flex min-w-0 items-center gap-2 font-semibold tracking-tight">
      <span className="flex size-6 shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground">
        <ChatIcon icon={MessagesSquare} size={14} aria-hidden="true" />
      </span>
      <span className="truncate">{brand}</span>
    </span>
  );
  return (
    <div
      className={cn(
        "flex h-full min-h-0 w-full overflow-hidden rounded-xl border border-border bg-background font-sans text-foreground antialiased shadow-[0_1px_2px_0_rgb(0_0_0/0.04)]",
        className,
      )}
    >
      {expanded && (
        <aside
          aria-label="Thread sidebar"
          className="hidden w-60 shrink-0 flex-col border-r border-border bg-muted/40 md:flex"
        >
          <div className="flex h-12 shrink-0 items-center justify-between gap-2 pl-4 pr-2.5 text-[13px]">
            {brandMark}
            <button
              type="button"
              aria-label="Collapse thread sidebar"
              onClick={() => setExpanded(false)}
              className={iconButton}
            >
              <ChatIcon icon={PanelLeft} size={15} />
            </button>
          </div>
          <div className="min-h-0 flex-1">{sidebar}</div>
        </aside>
      )}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <header className="flex h-12 shrink-0 items-center justify-between gap-3 border-b border-border/70 px-3 sm:px-4">
          <div className="flex min-w-0 items-center gap-2">
            <button
              type="button"
              aria-label="Open thread sidebar"
              onClick={() => {
                if (matchMedia("(min-width: 768px)").matches) setExpanded(true);
                else mobile.current?.showModal();
              }}
              className={cn(iconButton, expanded && "md:hidden")}
            >
              <ChatIcon icon={PanelLeft} size={15} />
            </button>
            <span className="truncate text-[13px] font-medium">{title}</span>
          </div>
          <div className="flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
            {actions}
          </div>
        </header>
        <main className="flex min-h-0 min-w-0 flex-1 flex-col">{children}</main>
      </div>
      <dialog
        ref={mobile}
        aria-label="Thread sidebar"
        className="fixed inset-y-0 left-0 right-auto m-0 h-dvh max-h-none w-[min(19rem,85vw)] max-w-none border-0 border-r border-border bg-background p-0 text-foreground shadow-2xl backdrop:bg-black/40 backdrop:backdrop-blur-[2px]"
      >
        <div className="flex h-full min-h-0 flex-col bg-muted/40">
          <div className="flex h-12 shrink-0 items-center justify-between gap-2 pl-4 pr-2.5 text-[13px]">
            {brandMark}
            <button
              type="button"
              aria-label="Close thread sidebar"
              onClick={() => mobile.current?.close()}
              className={iconButton}
            >
              <ChatIcon icon={X} size={15} />
            </button>
          </div>
          <div
            className="min-h-0 flex-1"
            onClick={(event) => {
              if (
                event.target instanceof Element &&
                event.target.closest("[data-thread-navigation]")
              ) {
                if (event.target.closest("[data-thread-editable]")) {
                  if (closeTimer.current) clearTimeout(closeTimer.current);
                  closeTimer.current = setTimeout(() => {
                    closeTimer.current = null;
                    mobile.current?.close();
                  }, doubleClickDelayMs);
                } else mobile.current?.close();
              }
            }}
            onDoubleClick={(event) => {
              if (
                event.target instanceof Element &&
                event.target.closest("[data-thread-editable]")
              ) {
                if (closeTimer.current) clearTimeout(closeTimer.current);
                closeTimer.current = null;
              }
            }}
          >
            {sidebar}
          </div>
        </div>
      </dialog>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { CirclePause } from "lucide-react";
import {
  AgentProvider,
  useAgentActions,
  useAgentState,
} from "@agentdock-ai/react";
import type { ChatProps } from "./types";
import { ChatShell } from "./chat-shell";
import { ChatViewport } from "./chat-viewport";
import { MessageList } from "./message-list";
import { EmptyState, Suggestions } from "./empty-state";
import { Composer } from "./composer";
import { ErrorState } from "./error-state";
import { Button } from "./ui/button";
import { ChatIcon } from "./icon";
import { useChatAttachments } from "./use-chat-attachments";

export function Chat(props: ChatProps) {
  return (
    <AgentProvider store={props.store}>
      <ChatSurface {...props} />
    </AgentProvider>
  );
}
function ChatSurface({
  adapter,
  className,
  disabled,
  showReasoning = true,
  suggestions,
  welcomeTitle,
  welcomeDescription,
  placeholder,
  onActivityChange,
}: ChatProps) {
  const {
    renderModel: model,
    agent,
    streamStatus,
    conversationActions,
  } = useAgentState();
  const actions = useAgentActions(adapter);
  const [draft, setDraft] = useState("");
  const attachments = useChatAttachments(adapter.attachments);
  const active =
    actions.busy ||
    (streamStatus === "consuming" &&
      !["completed", "failed", "cancelled"].includes(agent.status));
  useEffect(() => {
    onActivityChange?.(active);
  }, [active, onActivityChange]);
  const waiting = agent.status === "waiting" && streamStatus !== "stopped";
  const paused = waiting && agent.interrupts.length === 0;
  const blocksInput = waiting && !conversationActions?.canStart;
  const items = model.turns.at(-1)?.items ?? [];
  const activity = items.some(
    (item) =>
      (item.type === "tool-call" && item.active) ||
      (item.type === "tool-timeline" &&
        item.tools.some((tool) => tool.active)) ||
      (item.type === "approval" && item.approval.state === "pending") ||
      (item.type === "message" &&
        item.role === "assistant" &&
        showReasoning &&
        item.blocks.some(
          (b) => b.type === "reasoning" && b.state === "streaming",
        )),
  );
  const empty = model.turns.length === 0;
  const latestUser = model.turns
    .flatMap((turn) => turn.items)
    .filter((item) => item.type === "message" && item.role === "user")
    .at(-1);
  const latestUserId =
    latestUser?.type === "message" ? latestUser.messageId : undefined;
  async function submit(text: string) {
    if (
      disabled ||
      active ||
      blocksInput ||
      attachments.blocked ||
      (!text.trim() && attachments.items.length === 0)
    )
      return;
    const sent = attachments.take();
    setDraft("");
    const successful = await actions.sendMessage(
      text,
      sent.flatMap((item) => (item.attachment ? [item.attachment] : [])),
    );
    if (!successful) {
      setDraft((current) => current || text);
      attachments.restore(sent);
    }
  }
  let status = "";
  if (actions.cancelling) status = "Stopping…";
  else if (actions.respondingTo) status = "Sending response…";
  else if (paused) status = "Run paused";
  else if (waiting) status = "Waiting for your response";
  else if (active) status = "Agent is working";
  else if (streamStatus === "error") status = "Connection interrupted";
  else if (streamStatus === "stopped") status = "Stream stopped";
  else if (agent.status === "completed") status = "Response complete";
  else if (agent.status === "failed") status = "Run failed";
  else if (agent.status === "cancelled") status = "Run stopped";
  return (
    <ChatShell
      className={className}
      empty={empty}
      footer={
        <>
          {empty && (
            <EmptyState title={welcomeTitle} description={welcomeDescription} />
          )}
          <Composer
            key="composer"
            value={draft}
            onChange={setDraft}
            onSubmit={() => {
              void submit(draft);
            }}
            onStop={
              actions.canCancel && agent.runId
                ? () => {
                    void actions.cancelRun();
                  }
                : undefined
            }
            busy={active}
            waiting={blocksInput}
            cancelling={actions.cancelling}
            disabled={disabled}
            placeholder={placeholder}
            attachments={attachments.items}
            attachmentAccept={adapter.attachments?.accept}
            attachmentError={attachments.error}
            attachmentBlocked={attachments.blocked}
            onFiles={adapter.attachments ? attachments.add : undefined}
            onRemoveAttachment={attachments.remove}
            onRetryAttachment={attachments.retry}
          />
          {empty && suggestions && (
            <Suggestions
              suggestions={suggestions}
              disabled={disabled || active}
              onSubmit={(text) => {
                void submit(text);
              }}
            />
          )}
          <span
            role="status"
            aria-live="polite"
            aria-atomic="true"
            className="sr-only"
          >
            {status}
          </span>
        </>
      }
    >
      <ChatViewport revision={model} latestUserId={latestUserId} empty={empty}>
        {!empty && (
          <MessageList
            model={model}
            thinking={active && !waiting && !activity}
            showReasoning={showReasoning}
            canRespond={
              actions.canRespond &&
              !active &&
              !disabled &&
              streamStatus !== "stopped"
            }
            respondingTo={actions.respondingTo}
            approvalError={
              actions.actionError?.scope === "approval"
                ? actions.actionError.message
                : undefined
            }
            onRespond={(id, decisions) => {
              void actions.respondToInterrupt(id, decisions);
            }}
          />
        )}
        {paused && (
          <div
            role="status"
            className="flex flex-wrap items-center justify-between gap-x-4 gap-y-3 rounded-xl border border-border bg-card px-4 py-3 text-[13px] leading-5 shadow-[0_1px_2px_0_rgb(0_0_0/0.04)]"
          >
            <p className="flex min-w-0 flex-1 basis-56 items-center gap-2.5 text-muted-foreground">
              <ChatIcon icon={CirclePause} size={16} aria-hidden="true" />
              {actions.canContinue
                ? "The run is paused. Continue when you’re ready."
                : "The run is paused. Continue it in your app."}
            </p>
            {actions.canContinue && (
              <Button
                variant="primary"
                disabled={active || disabled}
                onClick={() => {
                  void actions.continueRun();
                }}
              >
                {active ? "Continuing…" : "Continue run"}
              </Button>
            )}
          </div>
        )}
        {model.transportError &&
          actions.actionError?.scope !== "approval" &&
          actions.actionError?.scope !== "continue" && (
            <ErrorState {...model.transportError} />
          )}
        {actions.actionError?.scope === "cancel" && (
          <ErrorState
            title="Unable to stop"
            detail={actions.actionError.message}
          />
        )}
        {actions.actionError?.scope === "continue" && (
          <ErrorState
            title="Unable to continue"
            detail={actions.actionError.message}
          />
        )}
      </ChatViewport>
    </ChatShell>
  );
}

"use client";
