import { ChevronRight, ExternalLink, FileText, Link2 } from "lucide-react";
import { ChatIcon } from "./icon";
import type { RenderContentBlock } from "@agentdock-ai/ui-core";
import { StreamingText } from "./streaming-text";
import { Reasoning } from "./reasoning";
import { ImageAttachment } from "./image-attachment";
import { safeUrl, formatJson } from "./utils";
export function MessageContent({
  blocks,
  showReasoning,
}: {
  blocks: readonly RenderContentBlock[];
  showReasoning: boolean;
}) {
  return (
    <div className="min-w-0 space-y-3">
      {blocks.map((block) => {
        if (block.type === "text")
          return (
            <StreamingText
              key={block.id}
              text={block.text}
              active={block.state === "streaming"}
            />
          );
        if (block.type === "reasoning")
          return showReasoning ? (
            <Reasoning
              key={block.id}
              text={block.text}
              active={block.state === "streaming"}
            />
          ) : null;
        if (block.type === "custom")
          return (
            <details
              key={block.id}
              className="group/custom overflow-hidden rounded-xl border border-border text-[13px]"
            >
              <summary className="flex min-h-10 cursor-pointer list-none items-center gap-2 px-3 py-2 text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted/60 hover:text-foreground focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/60 motion-reduce:transition-none [&::-webkit-details-marker]:hidden">
                <ChatIcon
                  icon={ChevronRight}
                  size={13}
                  className="transition-transform duration-200 group-open/custom:rotate-90 motion-reduce:transition-none"
                />
                <span className="min-w-0 flex-1 truncate font-medium">
                  {block.name || "Additional content"}
                </span>
              </summary>
              <pre
                tabIndex={0}
                className="max-h-64 overflow-auto whitespace-pre-wrap border-t border-border/70 bg-muted/40 px-3.5 py-3 font-mono text-[12px] leading-5 text-muted-foreground outline-none [overflow-wrap:anywhere]"
              >
                {formatJson(block.data)}
              </pre>
            </details>
          );
        const url = safeUrl(block.url);
        if (
          block.type === "image" &&
          url &&
          (/^https?:/i.test(url) || url.startsWith("/"))
        )
          return <ImageAttachment key={`${block.id}:${url}`} url={url} />;
        const label =
          block.type === "citation"
            ? block.title || "View source"
            : block.type === "file"
              ? block.name || "File"
              : `${block.type[0]?.toUpperCase()}${block.type.slice(1)}`;
        const kind =
          block.type === "citation"
            ? "Source"
            : block.type === "file"
              ? "File"
              : "Attachment";
        const card = (
          <>
            <span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground">
              <ChatIcon
                icon={block.type === "citation" ? Link2 : FileText}
                size={16}
                aria-hidden="true"
              />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block truncate text-[13px] font-medium leading-5 text-foreground">
                {label}
              </span>
              <span className="block text-[12px] leading-4 text-muted-foreground">
                {url ? kind : `${kind} · Preview unavailable`}
              </span>
            </span>
            {url && (
              <ChatIcon
                icon={ExternalLink}
                size={14}
                aria-hidden="true"
                className="mr-1 text-muted-foreground"
              />
            )}
          </>
        );
        const cardStyle =
          "flex w-full max-w-sm items-center gap-3 rounded-xl border border-border bg-background p-1.5 pr-2.5 text-left shadow-[0_1px_2px_0_rgb(0_0_0/0.04)]";
        return url ? (
          <a
            key={block.id}
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className={`${cardStyle} outline-none transition-colors duration-150 hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none`}
          >
            {card}
          </a>
        ) : (
          <div key={block.id} className={cardStyle}>
            {card}
          </div>
        );
      })}
    </div>
  );
}

import { CircleStop } from "lucide-react";
import type { JsonValue, RenderModel } from "@agentdock-ai/ui-core";
import { ChatIcon } from "./icon";
import { Message } from "./message";
import { ToolTimeline } from "./tool-timeline";
import { ApprovalCard } from "./approval-card";
import { ThinkingIndicator } from "./thinking-indicator";
import { ErrorState } from "./error-state";
export function MessageList({
  model,
  thinking = false,
  showReasoning,
  canRespond,
  respondingTo,
  approvalError,
  onRespond,
}: {
  model: RenderModel;
  thinking?: boolean;
  showReasoning: boolean;
  canRespond: boolean;
  respondingTo: string | null;
  approvalError?: string;
  onRespond: (interruptId: string, decisions: readonly JsonValue[]) => void;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-8">
      {model.turns.map((turn) => (
        <div
          key={
            turn.items.find(
              (item) => item.type === "message" && item.role === "user",
            )?.id ?? turn.id
          }
          className="flex min-w-0 flex-col gap-4"
          data-turn={turn.id}
        >
          {turn.items.map((item) => {
            switch (item.type) {
              case "message":
                return (
                  <Message
                    key={item.id}
                    message={item}
                    showReasoning={showReasoning}
                    showActions={
                      turn.items
                        .filter(
                          (i) => i.type === "message" && i.role === "assistant",
                        )
                        .at(-1)?.id === item.id
                    }
                  />
                );
              case "tool-call":
                return <ToolTimeline key={item.id} tools={[item]} />;
              case "tool-timeline":
                return <ToolTimeline key={item.id} tools={item.tools} />;
              case "approval":
                return (
                  <ApprovalCard
                    key={item.id}
                    approval={item.approval}
                    enabled={canRespond && turn.state === "waiting"}
                    error={approvalError}
                    pending={respondingTo === item.approval.interruptId}
                    onRespond={(decisions) =>
                      onRespond(item.approval.interruptId, decisions)
                    }
                  />
                );
              case "error":
                return <ErrorState key={item.id} {...item.error} />;
            }
          })}
          {thinking && turn === model.turns.at(-1) && (
            <ThinkingIndicator
              label={
                turn.items.some(
                  (item) =>
                    item.type === "message" &&
                    item.role === "assistant" &&
                    item.blocks.some(
                      (block) => block.type === "text" && block.text.trim(),
                    ),
                )
                  ? "working"
                  : "thinking"
              }
            />
          )}
          {(turn.state === "stopped" || turn.transportState === "stopped") && (
            <p className="flex items-center gap-1.5 px-1 text-xs text-muted-foreground">
              <ChatIcon icon={CircleStop} size={13} aria-hidden="true" />
              Stopped · Your partial answer is preserved.
            </p>
          )}
        </div>
      ))}
    </div>
  );
}

import type { RenderMessageItem } from "@agentdock-ai/ui-core";
import { MessageContent } from "./message-content";
import { ChatActionBar } from "./chat-action-bar";
import { ToolMessage } from "./tool-message";
export function Message({
  message,
  showReasoning,
  showActions = true,
}: {
  message: RenderMessageItem;
  showReasoning: boolean;
  showActions?: boolean;
}) {
  if (message.role === "tool") return <ToolMessage message={message} />;
  const user = message.role === "user";
  const blocks = showReasoning
    ? message.blocks
    : message.blocks.filter((b) => b.type !== "reasoning");
  if (!blocks.length) return null;
  const images = user ? blocks.filter((block) => block.type === "image") : [];
  const body = user ? blocks.filter((block) => block.type !== "image") : blocks;
  const answer = blocks
    .flatMap((b) => (b.type === "text" ? [b.text] : []))
    .join("\n\n");
  return (
    <article
      data-role={message.role}
      data-message-id={message.id}
      aria-label={user ? "You" : "Assistant"}
      className={
        user
          ? "ml-auto flex min-w-0 max-w-[90%] flex-col items-end gap-2 sm:max-w-[80%]"
          : "group/message min-w-0 w-full px-1"
      }
    >
      {user ? (
        <>
          {images.length > 0 && (
            <div
              aria-label="Attached images"
              className="flex max-w-full flex-wrap justify-end gap-2"
            >
              {images.map((block) => (
                <MessageContent
                  key={block.id}
                  blocks={[block]}
                  showReasoning={showReasoning}
                />
              ))}
            </div>
          )}
          {body.length > 0 && (
            <div className="min-w-0 max-w-full rounded-[20px] bg-muted px-4 py-2.5 text-[14px] leading-[1.6] [overflow-wrap:anywhere]">
              {body.map((block) =>
                block.type === "text" ? (
                  <span key={block.id} className="whitespace-pre-wrap">
                    {block.text}
                  </span>
                ) : (
                  <MessageContent
                    key={block.id}
                    blocks={[block]}
                    showReasoning={showReasoning}
                  />
                ),
              )}
            </div>
          )}
        </>
      ) : (
        <MessageContent blocks={blocks} showReasoning={showReasoning} />
      )}
      {!user && showActions && message.state !== "streaming" && answer && (
        <ChatActionBar text={answer} />
      )}
    </article>
  );
}

