"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Check, LoaderCircle, Search, SquarePen, X } from "lucide-react";
import { ChatIcon } from "./icon";
const doubleClickDelayMs = 250;
export interface ChatThread {
  id: string;
  title: string;
  /** Show activity while the app's agent is running this thread. */
  isRunning?: boolean;
}
/** Controlled navigation only. The app owns threads, persistence and authorization. */
export function ThreadSidebar({
  threads,
  selectedId,
  onSelect,
  onNew,
  onRename,
  footer,
}: {
  threads: readonly ChatThread[];
  selectedId: string;
  onSelect: (id: string) => void;
  onNew: () => void;
  onRename?: (id: string, title: string) => void;
  footer?: ReactNode;
}) {
  const [search, setSearch] = useState("");
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const pendingSelection = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (pendingSelection.current) clearTimeout(pendingSelection.current);
    },
    [],
  );
  function selectThread(id: string) {
    if (pendingSelection.current) clearTimeout(pendingSelection.current);
    pendingSelection.current = setTimeout(() => {
      pendingSelection.current = null;
      onSelect(id);
    }, doubleClickDelayMs);
  }
  function renameThread(thread: ChatThread) {
    if (pendingSelection.current) clearTimeout(pendingSelection.current);
    pendingSelection.current = null;
    setDraft(thread.title);
    setRenamingId(thread.id);
  }
  const visible = threads.filter((thread) =>
    thread.title.toLowerCase().includes(search.toLowerCase()),
  );
  return (
    <nav
      aria-label="Threads"
      className="flex h-full min-h-0 flex-col text-[13px]"
    >
      <div className="space-y-2 px-3 pb-2 pt-1">
        <button
          type="button"
          data-thread-navigation
          onClick={onNew}
          className="flex min-h-8 w-full items-center gap-2 rounded-lg px-2.5 text-left font-medium outline-none transition-colors duration-150 hover:bg-background/80 focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10"
        >
          <ChatIcon icon={SquarePen} size={15} aria-hidden="true" />
          New thread
        </button>
        <label className="flex min-h-8 items-center gap-2 rounded-lg border border-border/70 bg-background px-2.5 text-muted-foreground transition-colors duration-150 focus-within:border-ring/60 motion-reduce:transition-none">
          <ChatIcon icon={Search} size={14} aria-hidden="true" />
          <input
            aria-label="Search threads"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search threads"
            className="min-w-0 flex-1 bg-transparent py-1 text-[13px] text-foreground outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-base"
          />
        </label>
      </div>
      <div className="min-h-0 flex-1 overflow-auto px-3 pb-3">
        <p className="px-2.5 pb-1.5 pt-3 text-[11px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
          Conversations
        </p>
        <ul className="space-y-0.5">
          {visible.map((thread) => (
            <li key={thread.id}>
              {renamingId === thread.id ? (
                <form
                  className="flex min-h-8 items-center gap-1"
                  onSubmit={(event) => {
                    event.preventDefault();
                    const title = draft.trim();
                    if (title && onRename) onRename(thread.id, title);
                    setRenamingId(null);
                  }}
                >
                  <input
                    autoFocus
                    aria-label="Conversation title"
                    value={draft}
                    onChange={(event) => setDraft(event.target.value)}
                    maxLength={200}
                    className="min-w-0 flex-1 rounded-lg border border-ring/60 bg-background px-2.5 py-1 outline-none ring-4 ring-ring/10"
                  />
                  <button
                    type="submit"
                    aria-label="Save title"
                    className="flex size-7 items-center justify-center rounded-lg text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
                  >
                    <ChatIcon icon={Check} size={14} />
                  </button>
                  <button
                    type="button"
                    aria-label="Cancel rename"
                    onClick={() => setRenamingId(null)}
                    className="flex size-7 items-center justify-center rounded-lg text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
                  >
                    <ChatIcon icon={X} size={14} />
                  </button>
                </form>
              ) : (
                <div className="group flex min-h-8 items-center gap-1">
                  <button
                    type="button"
                    aria-current={selectedId === thread.id ? "page" : undefined}
                    data-thread-navigation
                    data-thread-editable={onRename ? "" : undefined}
                    onClick={() =>
                      onRename ? selectThread(thread.id) : onSelect(thread.id)
                    }
                    onDoubleClick={() => onRename && renameThread(thread)}
                    title={thread.title}
                    aria-label={`${thread.title}${thread.isRunning ? ", agent is working" : ""}`}
                    className={`flex min-h-8 min-w-0 flex-1 items-center gap-2 rounded-lg px-2.5 py-1 text-left outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10 ${selectedId === thread.id ? "bg-background font-medium text-foreground shadow-[0_1px_2px_0_rgb(0_0_0/0.06)] ring-1 ring-border/70" : "text-muted-foreground hover:bg-background/60 hover:text-foreground"}`}
                  >
                    <span className="min-w-0 flex-1 truncate">
                      {thread.title}
                    </span>
                    {thread.isRunning && (
                      <span
                        title="Agent is working"
                        className="flex shrink-0 items-center text-muted-foreground"
                      >
                        <ChatIcon
                          icon={LoaderCircle}
                          size={13}
                          aria-hidden="true"
                          className="motion-safe:animate-spin"
                        />
                      </span>
                    )}
                  </button>
                </div>
              )}
            </li>
          ))}
        </ul>
        {!visible.length && (
          <p className="px-2.5 py-2 text-xs text-muted-foreground">
            No conversations found
          </p>
        )}
      </div>
      {footer && (
        <div className="shrink-0 border-t border-border/70 px-5 py-3 text-xs text-muted-foreground">
          {footer}
        </div>
      )}
    </nav>
  );
}

"use client";
import { useState } from "react";
import { ChevronRight, CircleAlert, Wrench } from "lucide-react";
import { ChatIcon } from "./icon";
import { ShimmerText } from "./shimmer-text";
import type { RenderToolCallItem } from "@agentdock-ai/ui-core";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "./ui/collapsible";
import { ErrorState } from "./error-state";
import { formatJson } from "./utils";

export function ToolCall({ item }: { item: RenderToolCallItem }) {
  const [open, setOpen] = useState(false);
  const { tool, active } = item;
  const failed = tool.status === "failed";
  const running = active && tool.status === "running";
  const status = failed
    ? "Failed"
    : tool.status === "approval"
      ? "Needs approval"
      : running
        ? "Running"
        : tool.status === "complete"
          ? "Complete"
          : "Stopped";
  const progress = running
    ? tool.progress
        .flatMap((part) => (part.type === "text" ? [part.text] : []))
        .at(-1)
    : undefined;

  return (
    <Collapsible open={open} onOpenChange={setOpen} className="min-w-0">
      <CollapsibleTrigger
        aria-label={`${tool.name} ${status}`}
        className="group/tool flex min-h-7 max-w-full min-w-0 items-center gap-2 rounded-md text-left text-[13px] leading-5 text-muted-foreground outline-none transition-colors duration-150 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 motion-reduce:transition-none [@media(pointer:coarse)]:min-h-10"
      >
        <ChatIcon
          icon={failed ? CircleAlert : Wrench}
          size={13}
          aria-hidden="true"
          className={failed ? "text-destructive" : "opacity-60"}
        />
        <ShimmerText
          active={running}
          className="min-w-0 truncate font-mono text-[12.5px]"
        >
          {tool.name}
        </ShimmerText>
        {status !== "Complete" && status !== "Running" && (
          <span
            className={`shrink-0 text-[12px] ${failed ? "text-destructive" : ""}`}
          >
            {status}
          </span>
        )}
        <ChatIcon
          icon={ChevronRight}
          size={13}
          aria-hidden="true"
          className={`shrink-0 transition-[transform,opacity] duration-200 motion-reduce:transition-none ${open ? "rotate-90 opacity-100" : "opacity-0 group-hover/tool:opacity-100 group-focus-visible/tool:opacity-100 [@media(hover:none)]:opacity-50"}`}
        />
      </CollapsibleTrigger>
      {progress && (
        <p
          role="status"
          className="mb-1 ml-[1.3125rem] line-clamp-2 text-[12px] leading-5 text-muted-foreground [overflow-wrap:anywhere]"
        >
          {progress}
        </p>
      )}
      <CollapsibleContent>
        <div className="mb-2 ml-[1.3125rem] mt-1 space-y-2.5">
          <Payload title="Input" value={tool.input} />
          {tool.progress.length > 0 && (
            <Payload
              title="Progress"
              value={tool.progress
                .map((part) => ("text" in part ? part.text : formatJson(part)))
                .join("\n")}
            />
          )}
          {tool.output !== undefined && !failed && (
            <Payload title="Output" value={tool.output} />
          )}
          {failed && (
            <ErrorState
              title="Tool failed"
              detail={
                tool.error ??
                (typeof tool.output === "string"
                  ? tool.output
                  : "The tool returned an error.")
              }
            />
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
}

function Payload({ title, value }: { title: string; value: unknown }) {
  return (
    <div className="min-w-0">
      <p className="mb-1 text-[12px] leading-4 text-muted-foreground">
        {title}
      </p>
      <pre
        tabIndex={0}
        aria-label={title}
        className="max-h-60 max-w-full overflow-auto whitespace-pre-wrap rounded-lg bg-muted/60 px-3 py-2 font-mono text-[12px] leading-5 text-foreground/80 outline-none focus-visible:ring-2 focus-visible:ring-ring/60 [overflow-wrap:anywhere]"
      >
        {formatJson(value)}
      </pre>
    </div>
  );
}

